begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select ok(not has_function_privilege('anon','public.revise_native_publisher_content(uuid,text,text,uuid,bigint,bigint,text,jsonb,timestamptz,text,text)','execute'),'anon cannot revise');
select ok(not has_function_privilege('authenticated','public.revise_native_publisher_content(uuid,text,text,uuid,bigint,bigint,text,jsonb,timestamptz,text,text)','execute'),'authenticated cannot revise');
select ok(not has_table_privilege('service_role','public.native_publisher_revisions','insert'),'service role cannot forge revision receipts');
select ok(not has_table_privilege('service_role','public.native_publisher_revisions','update'),'service role cannot rewrite revision receipts');
select ok(not has_table_privilege('authenticated','public.native_publisher_revisions','select'),'authenticated cannot read other tenant receipts');
select ok(has_function_privilege('service_role','public.revise_native_publisher_content(uuid,text,text,uuid,bigint,bigint,text,jsonb,timestamptz,text,text)','execute'),'service role can revise');
insert into public.companies(user_id,id,name) values ('rev-user','rev-company','Revision Demo'),('rev-other','rev-company','Other Revision Demo');
update public.publisher_queue_ownership set owner='replacement',epoch=2,cutoff_at=now(),reconciliation_sha256=repeat('a',64),transferred_at=now() where source='legacy_spp';
select public.ingest_native_publisher_content('rev-user','rev-company','greg_brain','revision-reel','reel','Old caption','{"upload_paths":["rev-user/rev-company/old.mp4"],"cover_path":"rev-user/rev-company/old.jpg"}','2099-10-30T08:30Z',array['facebook','instagram'],'ready',null);
create temporary table original_item as select * from public.publisher_content_items where source_id='revision-reel';
create temporary table original_deliveries as select d.* from public.publisher_deliveries d join original_item i on i.id=d.content_item_id;
create function pg_temp.revise(req uuid default '41000000-0000-4000-8000-000000000001', usr text default 'rev-user', ep bigint default 2, ver bigint default 0, cap text default 'New caption', med jsonb default '{"upload_paths":["rev-user/rev-company/new.mp4"],"cover_path":"rev-user/rev-company/new.jpg"}', due timestamptz default '2099-10-31T08:30Z') returns jsonb language sql as $$
select public.revise_native_publisher_content(req,usr,'rev-company',(select id from original_item),ep,ver,cap,med,due,'approved:synthetic-revision','qa:synthetic'); $$;
select throws_ok($$select pg_temp.revise(usr=>'rev-other')$$,'P0002',null,'same company slug cannot cross user boundary');
select throws_ok($$select pg_temp.revise(ep=>1)$$,'40001',null,'stale ownership epoch fails');
select throws_ok($$select pg_temp.revise(ver=>9)$$,'40001',null,'stale lifecycle version fails');
select throws_ok($$select pg_temp.revise(due=>'2020-01-01')$$,'22023',null,'past revision schedule fails');
select throws_ok($$select pg_temp.revise(med=>'{"upload_paths":["rev-other/rev-company/new.mp4"]}')$$,'22023',null,'media cannot cross tenant');
select throws_ok($$select pg_temp.revise(med=>'{"upload_paths":["rev-user/rev-company/new.mp4"],"cover_path":"rev-other/rev-company/new.jpg"}')$$,'22023',null,'cover cannot cross tenant');
select throws_ok($$select pg_temp.revise(med=>'{"media_urls":["https://example.com/new.mp4"]}')$$,'22023',null,'external media cannot replace tenant-owned uploads');
select is((select caption from public.publisher_content_items where id=(select id from original_item)),'Old caption','failed validation preserves old caption');
select is((select media from public.publisher_content_items where id=(select id from original_item)),(select media from original_item),'failed validation preserves old media');
create temporary table revision_result as select pg_temp.revise() result;
select is((select result->>'revised' from revision_result),'true','revision succeeds');
select is((select result->>'replayed' from revision_result),'false','first request is not replay');
select is((select result->>'content_item_id' from revision_result),(select id::text from original_item),'content identity preserved');
select is((select lifecycle_version from public.publisher_content_items where id=(select id from original_item)),1::bigint,'revision advances lifecycle once');
select is((select caption from public.publisher_content_items where id=(select id from original_item)),'New caption','caption replaced');
select is((select scheduled_at from public.publisher_content_items where id=(select id from original_item)),'2099-10-31T08:30Z'::timestamptz,'schedule replaced');
select is((select media->'upload_paths'->>0 from public.publisher_content_items where id=(select id from original_item)),'rev-user/rev-company/new.mp4','video replaced');
select is((select media->>'cover_path' from public.publisher_content_items where id=(select id from original_item)),'rev-user/rev-company/new.jpg','thumbnail replaced');
select is((select ingestion_envelope from public.publisher_content_items where id=(select id from original_item)),(select ingestion_envelope from original_item),'immutable original envelope preserved');
select is((select ingestion_fingerprint_sha256 from public.publisher_content_items where id=(select id from original_item)),(select ingestion_fingerprint_sha256 from original_item),'original ingestion fingerprint preserved');
select is((select count(*) from original_deliveries o join public.publisher_deliveries d using(id,content_item_id,platform,idempotency_key)),2::bigint,'platform identities and idempotency keys preserved');
select is((select count(*) from public.publisher_deliveries where content_item_id=(select id from original_item)),2::bigint,'revision creates no duplicate deliveries');
select is((select count(*) from public.publisher_deliveries where content_item_id=(select id from original_item) and state='pending' and next_attempt_at='2099-10-31T08:30Z'),2::bigint,'both due times replaced atomically');
select is(pg_temp.revise()->>'replayed','true','exact request replays despite stale expected version');
select is((select lifecycle_version from public.publisher_content_items where id=(select id from original_item)),1::bigint,'replay does not increment lifecycle');
select is((select count(*) from public.publisher_audit_log where content_item_id=(select id from original_item) and event_type='native_content_revised'),1::bigint,'replay emits no additional audit event');
select is((select details->'before'->>'caption' from public.publisher_audit_log where content_item_id=(select id from original_item) and event_type='native_content_revised'),'Old caption','audit records prior caption');
select is((select details->'after'->>'caption' from public.publisher_audit_log where content_item_id=(select id from original_item) and event_type='native_content_revised'),'New caption','audit records replacement caption');
select is((select count(*) from public.native_publisher_revisions),1::bigint,'failed validation leaves no orphan receipts');
update public.publisher_queue_ownership set epoch=3 where source='legacy_spp';
select is(pg_temp.revise()->>'replayed','true','receipt replay survives later ownership epoch change');
update public.publisher_queue_ownership set epoch=2 where source='legacy_spp';
select throws_ok($$select pg_temp.revise(cap=>'Conflicting caption')$$,'23505',null,'same request different payload conflicts');
select throws_ok($$select pg_temp.revise(req=>'41000000-0000-4000-8000-000000000002')$$,'40001',null,'new request with stale version conflicts');
select is((select count(*) from public.claim_publisher_deliveries(2,10,300,'2099-10-30T08:30Z')),0::bigint,'old booking no longer dispatches');
update public.publisher_deliveries set state='pending',attempt_count=1 where content_item_id=(select id from original_item) and platform='facebook';
select throws_ok($$select pg_temp.revise(req=>'41000000-0000-4000-8000-000000000003',ver=>1)$$,'55000',null,'attempt counter on one sibling prevents whole revision');
select is((select scheduled_at from public.publisher_content_items where id=(select id from original_item)),'2099-10-31T08:30Z'::timestamptz,'refusal keeps effective date');
update public.publisher_deliveries set attempt_count=0 where content_item_id=(select id from original_item) and platform='facebook';
update public.publisher_deliveries set state='verification_required' where content_item_id=(select id from original_item) and platform='facebook';
select throws_ok($$select pg_temp.revise(req=>'41000000-0000-4000-8000-000000000003',ver=>1)$$,'55000',null,'ambiguous delivery on one sibling prevents whole revision');
select is((select scheduled_at from public.publisher_content_items where id=(select id from original_item)),'2099-10-31T08:30Z'::timestamptz,'refusal keeps effective date');
update public.publisher_deliveries set state='pending' where content_item_id=(select id from original_item) and platform='facebook';
update public.publisher_deliveries set state='succeeded',platform_post_id='synthetic:published',published_at=now() where content_item_id=(select id from original_item) and platform='facebook';
select throws_ok($$select pg_temp.revise(req=>'41000000-0000-4000-8000-000000000003',ver=>1)$$,'55000',null,'partial success on one sibling prevents whole revision');
select is((select scheduled_at from public.publisher_content_items where id=(select id from original_item)),'2099-10-31T08:30Z'::timestamptz,'refusal keeps effective date');
update public.publisher_deliveries set state='pending',platform_post_id=null,published_at=null where content_item_id=(select id from original_item) and platform='facebook';
update public.publisher_deliveries set state='leased',lease_token=gen_random_uuid(),lease_expires_at=now()+interval '1 minute',lease_phase='pre_dispatch' where content_item_id=(select id from original_item) and platform='facebook';
select throws_ok($$select pg_temp.revise(req=>'41000000-0000-4000-8000-000000000003',ver=>1)$$,'55000',null,'pre-dispatch lease on one sibling prevents whole revision');
select is((select scheduled_at from public.publisher_content_items where id=(select id from original_item)),'2099-10-31T08:30Z'::timestamptz,'refusal keeps effective date');
update public.publisher_deliveries set state='pending',lease_token=null,lease_expires_at=null,lease_phase=null where content_item_id=(select id from original_item) and platform='facebook';
update public.publisher_deliveries set state='leased',lease_token=gen_random_uuid(),lease_expires_at=now()+interval '1 minute',lease_phase='dispatch_started' where content_item_id=(select id from original_item) and platform='facebook';
select throws_ok($$select pg_temp.revise(req=>'41000000-0000-4000-8000-000000000003',ver=>1)$$,'55000',null,'dispatch-started lease on one sibling prevents whole revision');
select is((select scheduled_at from public.publisher_content_items where id=(select id from original_item)),'2099-10-31T08:30Z'::timestamptz,'refusal keeps effective date');
update public.publisher_deliveries set state='pending',lease_token=null,lease_expires_at=null,lease_phase=null where content_item_id=(select id from original_item) and platform='facebook';
update public.publisher_deliveries set platform_post_id='synthetic:unknown' where content_item_id=(select id from original_item) and platform='facebook';
select throws_ok($$select pg_temp.revise(req=>'41000000-0000-4000-8000-000000000003',ver=>1)$$,'55000',null,'provider identity on one sibling prevents whole revision');
select is((select scheduled_at from public.publisher_content_items where id=(select id from original_item)),'2099-10-31T08:30Z'::timestamptz,'refusal keeps effective date');
update public.publisher_deliveries set platform_post_id=null where content_item_id=(select id from original_item) and platform='facebook';
update public.publisher_deliveries set provider_reconciliation_metadata='{"container_id":"synthetic"}' where content_item_id=(select id from original_item) and platform='facebook';
select throws_ok($$select pg_temp.revise(req=>'41000000-0000-4000-8000-000000000003',ver=>1)$$,'55000',null,'reconciliation state on one sibling prevents whole revision');
select is((select scheduled_at from public.publisher_content_items where id=(select id from original_item)),'2099-10-31T08:30Z'::timestamptz,'refusal keeps effective date');
update public.publisher_deliveries set provider_reconciliation_metadata='{}' where content_item_id=(select id from original_item) and platform='facebook';
insert into public.publisher_delivery_attempts(delivery_id,attempt_number,idempotency_key,lease_token,state,finished_at)
select id,1,'synthetic:revision-history',gen_random_uuid(),'dead_letter',now() from public.publisher_deliveries where content_item_id=(select id from original_item) and platform='facebook';
select throws_ok($$select pg_temp.revise(req=>'41000000-0000-4000-8000-000000000004',ver=>1)$$,'55000',null,'historical attempt refuses revision even when counter reset');
select is(pg_temp.revise()->>'replayed','true','stored request remains replayable after downstream history');
select throws_ok($$select pg_temp.revise(cap=>'Changed after dispatch')$$,'23505',null,'conflicting replay still rejected after downstream history');
select is((select ingestion_envelope from public.publisher_content_items where id=(select id from original_item)),(select ingestion_envelope from original_item),'original ingestion remains intact after all failures');
select is((public.ingest_native_publisher_content('rev-user','rev-company','greg_brain','revision-reel','reel','Old caption','{"upload_paths":["rev-user/rev-company/old.mp4"],"cover_path":"rev-user/rev-company/old.jpg"}','2099-10-30T08:30Z',array['facebook','instagram'],'ready',null)->>'created'),'false','original ingestion replays after revision without resurrecting old media');
select is((select media->'upload_paths'->>0 from public.publisher_content_items where id=(select id from original_item)),'rev-user/rev-company/new.mp4','ingestion replay cannot restore superseded video');
delete from public.publisher_delivery_attempts where idempotency_key='synthetic:revision-history';
create temporary table new_claims as select * from public.claim_publisher_deliveries(2,10,300,'2099-10-31T08:30Z');
select is((select count(*) from new_claims),2::bigint,'replacement booking claims exactly once per platform at new date');
select is((select count(*) from new_claims where media->'upload_paths'->>0='rev-user/rev-company/new.mp4' and caption='New caption'),2::bigint,'worker receives replacement media and caption');
select is(pg_temp.revise()->>'replayed','true','receipt replays after actual worker claim');
select is(pg_temp.revise()->'deliveries',(select result->'deliveries' from revision_result),'receipt returns original result snapshot after dispatch advances');
select is((select count(*) from public.publisher_deliveries where content_item_id=(select id from original_item) and state='leased'),2::bigint,'replay never rewinds worker leases');
select throws_ok($$select pg_temp.revise(cap=>'Changed after worker claim')$$,'23505',null,'conflicting receipt remains rejected after actual claim');
set local timezone = 'Australia/Sydney';
select is(pg_temp.revise()->>'replayed','true','receipt fingerprint is stable across session time zones');
select * from finish();
rollback;
